{"metodo_reparado": "        @Test
        @DisplayName("Deve retornar 200 OK com todos os campos e as tags na ordem de cadastro quando o produto existir")
        @Sql({"/fixtures/limpeza.sql", "/fixtures/produto/produtos.sql"})
        void shouldReturn200WithAllFieldsWhenProductExists() throws Exception {
            mockMvc.perform(get("/produtos/1"))
                    .andExpect(status().isOk())
                    .andExpect(jsonPath("$.id").value(is(1)))
                    .andExpect(jsonPath("$.sku").value("LIV-002"))
                    .andExpect(jsonPath("$.nome").value("Livro de Java"))
                    .andExpect(jsonPath("$.resumo").value("Livro sobre Java"))
                    .andExpect(jsonPath("$.preco").value(decimal("89.90")))
                    .andExpect(jsonPath("$.categoria").value("LIVROS"))
                    .andExpect(jsonPath("$.ativo").value(true))
                    .andExpect(jsonPath("$.estoque").value(is(7)))
                    .andExpect(jsonPath("$.pesoGramas").value(is(600)))
                    .andExpect(jsonPath("$.dimensoes.alturaCm").value(is(23)))
                    .andExpect(jsonPath("$.dimensoes.larguraCm").value(is(16)))
                    .andExpect(jsonPath("$.dimensoes.comprimentoCm").value(is(3)))
                    .andExpect(jsonPath("$.tags").value(contains("programacao", "java")));
        }"}

{"metodo_reparado": "        @Test
        @DisplayName("Deve retornar 200 OK com todos os campos quando a cotação for válida (PADRAO para SP, 500 g: 15,00 + 1 × 2,00 = 17,00, prazo 3)")
        @Sql({"/fixtures/limpeza.sql", "/fixtures/frete/frete.sql"})
        void shouldReturn200WithAllFieldsWhenQuotationIsValid() throws Exception {
            mockMvc.perform(post("/fretes/cotacao")
                            .contentType(MediaType.APPLICATION_JSON)
                            .content("""
                                    {
                                      "destino": {"cep": "01001000", "uf": "SP"},
                                      "modalidade": "PADRAO",
                                      "itens": [{"produtoId": 1, "quantidade": 1}]
                                    }
                                    """))
                    .andExpect(status().isOk())
                    .andExpect(jsonPath("$.modalidade").value("PADRAO"))
                    .andExpect(jsonPath("$.valor").value(decimal("17.00")))
                    .andExpect(jsonPath("$.prazoDias").value(is(3)))
                    .andExpect(jsonPath("$.freteGratis").value(false));
        }"}

{"metodo_reparado": "        @Test
        @DisplayName("Deve baixar o estoque quando o pedido for criado (RN03: 5 − 2 = 3)")
        @Sql({"/fixtures/limpeza.sql", "/fixtures/regras/rn03.sql"})
        void shouldDecreaseStockWhenOrderIsCreated() throws Exception {
            mockMvc.perform(post("/pedidos")
                            .contentType(MediaType.APPLICATION_JSON)
                            .content("""
                                    {
                                      "carrinhoId": 103,
                                      "cliente": {"nome": "Ana Souza", "email": "ana@exemplo.com", "cpf": "12345678900"},
                                      "enderecoEntrega": {
                                        "logradouro": "Rua A", "numero": "10",
                                        "cidade": "Campinas", "uf": "SP", "cep": "13010000"
                                      },
                                      "modalidadeFrete": "PADRAO"
                                    }
                                    """))
                    .andExpect(status().isCreated());

            mockMvc.perform(get("/produtos/2"))
                    .andExpect(jsonPath("$.estoque").value(is(3)));
        }"}
